resolved as (
    select
        HUB_POLICY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SPECIAL_CONDITIONS end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then SPECIAL_CONDITIONS end)) as SPECIAL_CONDITIONS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DEDUCTIBLE_TOTAL end) as DEDUCTIBLE_TOTAL,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CO_PAYMENT_PERCENTAGE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CO_PAYMENT_PERCENTAGE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CO_PAYMENT_PERCENTAGE end)) as CO_PAYMENT_PERCENTAGE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then WARRANTY_CONDITIONS end) as WARRANTY_CONDITIONS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when SPECIAL_CONDITIONS is not null or DEDUCTIBLE_TOTAL is not null or CO_PAYMENT_PERCENTAGE is not null or WARRANTY_CONDITIONS is not null
                     then md5(upper(coalesce(cast(SPECIAL_CONDITIONS as varchar), '') || '|' || coalesce(cast(DEDUCTIBLE_TOTAL as varchar), '') || '|' || coalesce(cast(CO_PAYMENT_PERCENTAGE as varchar), '') || '|' || coalesce(cast(WARRANTY_CONDITIONS as varchar), '')))
                end as SAT_POLICY_TERMS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_TERMS_HASHDIFF is not null
